    flag_set = flags.split()
    show_names = "-n" in flag_set
    only_names = "-l" in flag_set
    ignore_case = "-i" in flag_set
    invert = "-v" in flag_set
    entire_line = "-x" in flag_set

    multiple_files = len(files) > 1
    result = []

    search_pattern = pattern.lower() if ignore_case else pattern

    for filename in files:
        with open(filename) as f:
            lines = f.readlines()

        file_matched = False
        for i, line in enumerate(lines, start=1):
            content = line.rstrip("\n")
            compare_content = content.lower() if ignore_case else content

            if entire_line:
                matches = compare_content == search_pattern
            else:
                matches = search_pattern in compare_content

            if invert:
                matches = not matches

            if matches:
                file_matched = True
                if only_names:
                    break

                prefix = ""
                if multiple_files:
                    prefix += filename + ":"
                if show_names:
                    prefix += str(i) + ":"
                result.append(prefix + content + "\n")

        if only_names and file_matched:
            result.append(filename + "\n")

    return "".join(result)
"}

