import (
	"fmt"
	"sort"
)

type Record struct {
	ID     int
	Parent int
	// feel free to add fields as you see fit
}

type Node struct {
	ID       int
	Children []*Node
	// feel free to add fields as you see fit
}

func Build(records []Record) (*Node, error) {
	if len(records) == 0 {
		return nil, nil
	}

	sorted := make([]Record, len(records))
	copy(sorted, records)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].ID < sorted[j].ID
	})

	nodes := make([]*Node, len(sorted))
	for i, record := range sorted {
		if record.ID != i {
			return nil, fmt.Errorf("records are not continuous: expected ID %d, got %d", i, record.ID)
		}
		if i == 0 {
			if record.Parent != 0 {
				return nil, fmt.Errorf("root node must have parent equal to its own ID, got %d", record.Parent)
			}
		} else if record.Parent >= record.ID {
			return nil, fmt.Errorf("node %d has invalid parent %d: parent must be lower than the node's ID", record.ID, record.Parent)
		}

		nodes[i] = &Node{ID: record.ID}
		if i != 0 {
			parent := nodes[record.Parent]
			parent.Children = append(parent.Children, nodes[i])
		}
	}

	return nodes[0], nil
}
"}

