{"file_path":"/root/proving-ground-runs/polyglot-harness-vs-product-sonnet-20260927T163411Z/cell-B0M4Hu/src/lib.rs","content":"use std::collections::HashMap;
use std::thread;

pub fn frequency(input: &[&str], worker_count: usize) -> HashMap<char, usize> {
    if input.is_empty() {
        return HashMap::new();
    }

    let worker_count = worker_count.max(1).min(input.len());
    let chunk_size = (input.len() + worker_count - 1) / worker_count;

    let results: Vec<HashMap<char, usize>> = thread::scope(|scope| {
        let handles: Vec<_> = input
            .chunks(chunk_size)
            .map(|chunk| {
                scope.spawn(move || {
                    let mut map = HashMap::new();
                    for line in chunk {
                        for c in line.chars() {
                            if let Some(c) = c.to_lowercase().next() {
                                if c.is_alphabetic() {
                                    *map.entry(c).or_insert(0) += 1;
                                }
                            }
                        }
                    }
                    map
                })
            })
            .collect();

        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });

    let mut total = HashMap::new();
    for map in results {
        for (k, v) in map {
            *total.entry(k).or_insert(0) += v;
        }
    }
    total
}
"}

