{"file_path":"/root/proving-ground-runs/polyglot-harness-vs-product-sonnet-20260927T163411Z/cell-DI9Wlb/poker.go","content":"package poker

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// card represents a single playing card with a rank and suit.
type card struct {
	rank int
	suit string
}

var validSuits = map[string]bool{
	"♤": true,
	"♡": true,
	"♢": true,
	"♧": true,
}

var rankNames = map[string]int{
	"J": 11,
	"Q": 12,
	"K": 13,
	"A": 14,
}

// parseCard parses a single card string like "4♤" or "10♢" into a card.
func parseCard(s string) (card, error) {
	if len(s) < 2 {
		return card{}, fmt.Errorf("invalid card: %q", s)
	}

	// Find where the suit starts. Suits are represented by a single
	// multi-byte rune, so we search backwards for the last rune.
	runes := []rune(s)
	if len(runes) < 2 {
		return card{}, fmt.Errorf("invalid card: %q", s)
	}

	suit := string(runes[len(runes)-1])
	rankStr := string(runes[:len(runes)-1])

	if !validSuits[suit] {
		return card{}, fmt.Errorf("invalid suit in card: %q", s)
	}
	if rankStr == "" {
		return card{}, fmt.Errorf("invalid rank in card: %q", s)
	}

	var rank int
	if r, ok := rankNames[rankStr]; ok {
		rank = r
	} else {
		n, err := strconv.Atoi(rankStr)
		if err != nil {
			return card{}, fmt.Errorf("invalid rank in card: %q", s)
		}
		if n < 2 || n > 10 {
			return card{}, fmt.Errorf("invalid rank in card: %q", s)
		}
		rank = n
	}

	return card{rank: rank, suit: suit}, nil
}

// parseHand parses a hand string into a sorted (descending) slice of cards.
func parseHand(hand string) ([]card, error) {
	parts := strings.Fields(hand)
	if len(parts) != 5 {
		return nil, fmt.Errorf("hand must have exactly 5 cards: %q", hand)
	}

	cards := make([]card, 0, 5)
	for _, p := range parts {
		c, err := parseCard(p)
		if err != nil {
			return nil, err
		}
		cards = append(cards, c)
	}

	sort.Slice(cards, func(i, j int) bool {
		return cards[i].rank > cards[j].rank
	})

	return cards, nil
}

// handScore contains the comparable representation of a hand's strength.
// category is the poker hand category (higher is better), and tiebreakers
// is a slice of ranks used to break ties within the same category, ordered
// from most to least significant.
type handScore struct {
	category    int
	tiebreakers []int
}

// compare returns 1 if h beats other, -1 if other beats h, 0 if tied.
func (h handScore) compare(other handScore) int {
	if h.category != other.category {
		if h.category > other.category {
			return 1
		}
		return -1
	}
	for i := 0; i < len(h.tiebreakers) && i < len(other.tiebreakers); i++ {
		if h.tiebreakers[i] != other.tiebreakers[i] {
			if h.tiebreakers[i] > other.tiebreakers[i] {
				return 1
			}
			return -1
		}
	}
	return 0
}

// evaluateHand computes the handScore for a set of 5 cards (already sorted
// descending by rank).
func evaluateHand(cards []card) handScore {
	// Count occurrences of each rank.
	counts := map[int]int{}
	for _, c := range cards {
		counts[c.rank]++
	}

	isFlush := true
	for i := 1; i < len(cards); i++ {
		if cards[i].suit != cards[0].suit {
			isFlush = false
			break
		}
	}

	// Determine straight. cards are sorted descending, unique ranks assumed
	// (a valid poker hand doesn't have duplicate rank+suit, but duplicate
	// ranks are possible with multiple decks so we must check for pairs).
	ranks := make([]int, len(cards))
	for i, c := range cards {
		ranks[i] = c.rank
	}

	isStraight, straightHigh := checkStraight(ranks)

	if isStraight && isFlush {
		return handScore{category: 8, tiebreakers: []int{straightHigh}}
	}

	// Group ranks by count for pair/trip/quad detection.
	type rc struct {
		rank  int
		count int
	}
	var groups []rc
	for r, c := range counts {
		groups = append(groups, rc{rank: r, count: c})
	}
	sort.Slice(groups, func(i, j int) bool {
		if groups[i].count != groups[j].count {
			return groups[i].count > groups[j].count
		}
		return groups[i].rank > groups[j].rank
	})

	if groups[0].count == 4 {
		tb := []int{groups[0].rank}
		for _, g := range groups[1:] {
			tb = append(tb, g.rank)
		}
		return handScore{category: 7, tiebreakers: tb}
	}

	if groups[0].count == 3 && len(groups) > 1 && groups[1].count == 2 {
		return handScore{category: 6, tiebreakers: []int{groups[0].rank, groups[1].rank}}
	}

	if isFlush {
		return handScore{category: 5, tiebreakers: ranks}
	}

	if isStraight {
		return handScore{category: 4, tiebreakers: []int{straightHigh}}
	}

	if groups[0].count == 3 {
		tb := []int{groups[0].rank}
		for _, g := range groups[1:] {
			tb = append(tb, g.rank)
		}
		return handScore{category: 3, tiebreakers: tb}
	}

	if groups[0].count == 2 && len(groups) > 1 && groups[1].count == 2 {
		tb := []int{groups[0].rank, groups[1].rank}
		for _, g := range groups[2:] {
			tb = append(tb, g.rank)
		}
		return handScore{category: 2, tiebreakers: tb}
	}

	if groups[0].count == 2 {
		tb := []int{groups[0].rank}
		for _, g := range groups[1:] {
			tb = append(tb, g.rank)
		}
		return handScore{category: 1, tiebreakers: tb}
	}

	return handScore{category: 0, tiebreakers: ranks}
}

// checkStraight determines whether the given descending-sorted ranks form a
// straight, handling the special case where an ace can be low (A-2-3-4-5).
// It returns whether it's a straight, and if so, the high card rank to use
// for comparisons (5 for the wheel straight A-2-3-4-5).
func checkStraight(ranks []int) (bool, int) {
	// Must all be distinct ranks.
	unique := map[int]bool{}
	for _, r := range ranks {
		if unique[r] {
			return false, 0
		}
		unique[r] = true
	}

	// ranks is sorted descending.
	consecutive := true
	for i := 1; i < len(ranks); i++ {
		if ranks[i-1]-ranks[i] != 1 {
			consecutive = false
			break
		}
	}
	if consecutive {
		return true, ranks[0]
	}

	// Check for wheel: A, 5, 4, 3, 2
	if ranks[0] == 14 && ranks[1] == 5 && ranks[2] == 4 && ranks[3] == 3 && ranks[4] == 2 {
		return true, 5
	}

	return false, 0
}

// BestHand returns the best poker hand(s) from the given list of hands.
func BestHand(hands []string) ([]string, error) {
	if len(hands) == 0 {
		return nil, fmt.Errorf("no hands given")
	}

	scores := make([]handScore, len(hands))
	for i, h := range hands {
		cards, err := parseHand(h)
		if err != nil {
			return nil, err
		}
		scores[i] = evaluateHand(cards)
	}

	var best []string
	var bestScore handScore
	for i, s := range scores {
		if best == nil {
			best = []string{hands[i]}
			bestScore = s
			continue
		}
		cmp := s.compare(bestScore)
		if cmp > 0 {
			best = []string{hands[i]}
			bestScore = s
		} else if cmp == 0 {
			best = append(best, hands[i])
		}
	}

	return best, nil
}
"}

