{"file_path":"/root/proving-ground-runs/polyglot-harness-vs-product-sonnet-20260927T163411Z/cell-KCPz5t/src/lib.rs","content":"/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    key: &'a [u8],
    pos: usize,
}

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key: AsRef<[u8]> + ?Sized>(key: &'a Key) -> Xorcism<'a> {
        Xorcism {
            key: key.as_ref(),
            pos: 0,
        }
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        for byte in data.iter_mut() {
            *byte ^= self.key[self.pos];
            self.pos = (self.pos + 1) % self.key.len();
        }
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<Data, I>(&mut self, data: Data) -> impl Iterator<Item = u8> + 'a
    where
        Data: IntoIterator<Item = I> + 'a,
        I: std::borrow::Borrow<u8>,
    {
        let key = self.key;
        let mut pos = self.pos;
        let iter = data.into_iter().map(move |b| {
            let out = b.borrow() ^ key[pos];
            pos = (pos + 1) % key.len();
            out
        });
        let result: Vec<u8> = iter.collect();
        self.pos = (self.pos + result.len()) % self.key.len();
        result.into_iter()
    }

    /// Wrap a `Read` implementation so it is XORed on the way through.
    #[cfg(feature = "io")]
    pub fn reader<R: std::io::Read + 'a>(self, reader: R) -> impl std::io::Read + 'a {
        XorReader {
            xorcism: self,
            reader,
        }
    }

    /// Wrap a `Write` implementation so it is XORed on the way through.
    #[cfg(feature = "io")]
    pub fn writer<W: std::io::Write + 'a>(self, writer: W) -> impl std::io::Write + 'a {
        XorWriter {
            xorcism: self,
            writer,
        }
    }
}

#[cfg(feature = "io")]
struct XorReader<'a, R> {
    xorcism: Xorcism<'a>,
    reader: R,
}

#[cfg(feature = "io")]
impl<'a, R: std::io::Read> std::io::Read for XorReader<'a, R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let n = self.reader.read(buf)?;
        self.xorcism.munge_in_place(&mut buf[..n]);
        Ok(n)
    }
}

#[cfg(feature = "io")]
struct XorWriter<'a, W> {
    xorcism: Xorcism<'a>,
    writer: W,
}

#[cfg(feature = "io")]
impl<'a, W: std::io::Write> std::io::Write for XorWriter<'a, W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let mut munged = buf.to_vec();
        self.xorcism.munge_in_place(&mut munged);
