#include <algorithm>
#include <array>
#include <numeric>
#include <random>

namespace dnd_character {

namespace {
int roll_die() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<int> dist(1, 6);
    return dist(gen);
}
}  // namespace

int modifier(int score) {
    int diff = score - 10;
    if (diff < 0) {
        return -(((-diff) + 1) / 2);
    }
    return diff / 2;
}

int ability() {
    std::array<int, 4> dice{roll_die(), roll_die(), roll_die(), roll_die()};
    std::sort(dice.begin(), dice.end());
    return dice[1] + dice[2] + dice[3];
}

Character::Character()
    : strength(ability()),
      dexterity(ability()),
      constitution(ability()),
      intelligence(ability()),
      wisdom(ability()),
      charisma(ability()),
      hitpoints(10 + modifier(constitution)) {
}

}  // namespace dnd_character
"}

