{"file_path":"/root/proving-ground-runs/polyglot-harness-vs-product-sonnet-20260927T163411Z/cell-YbcVlu/simple_linked_list.go","content":"package linkedlist

import "errors"

// Element is a node in the singly linked list.
type Element struct {
	value int
	next  *Element
}

// List is a singly linked list.
type List struct {
	head *Element
	size int
}

func New(elements []int) *List {
	l := &List{}
	for _, e := range elements {
		l.Push(e)
	}
	return l
}

func (l *List) Size() int {
	return l.size
}

func (l *List) Push(element int) {
	e := &Element{value: element, next: l.head}
	l.head = e
	l.size++
}

func (l *List) Pop() (int, error) {
	if l.head == nil {
		return 0, errors.New("pop from empty list")
	}
	v := l.head.value
	l.head = l.head.next
	l.size--
	return v, nil
}

