class binary_tree {
public:
    explicit binary_tree(const T& data) : data_(data) {}

    const T& data() const { return data_; }

    const std::unique_ptr<binary_tree<T>>& left() const { return left_; }
    const std::unique_ptr<binary_tree<T>>& right() const { return right_; }

    void insert(const T& value)
    {
        if (value < data_)
        {
            if (left_)
                left_->insert(value);
            else
                left_ = std::unique_ptr<binary_tree<T>>(new binary_tree<T>(value));
        }
        else
        {
            if (right_)
                right_->insert(value);
            else
                right_ = std::unique_ptr<binary_tree<T>>(new binary_tree<T>(value));
        }
    }

    class iterator {
    public:
        explicit iterator(typename std::vector<T>::const_iterator it) : it_(it) {}

        const T& operator*() const { return *it_; }

        iterator& operator++()
        {
            ++it_;
            return *this;
        }

        bool operator!=(const iterator& other) const { return it_ != other.it_; }
        bool operator==(const iterator& other) const { return it_ == other.it_; }

    private:
        typename std::vector<T>::const_iterator it_;
    };

    iterator begin() const
    {
        sorted_.clear();
        collect(sorted_);
        return iterator(sorted_.begin());
    }

    iterator end() const { return iterator(sorted_.end()); }

private:
    void collect(std::vector<T>& out) const
    {
        if (left_)
            left_->collect(out);
        out.push_back(data_);
        if (right_)
            right_->collect(out);
    }

    T data_;
    std::unique_ptr<binary_tree<T>> left_;
    std::unique_ptr<binary_tree<T>> right_;
    mutable std::vector<T> sorted_;
};

}  // namespace binary_search_tree

