    """Exception raised when Stack is not full.

    message: explanation of the error.
    """

    def __init__(self, message):
        self.message = message
        super().__init__(message)


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def evaluate(input_data):
    stack = []
    definitions = {}

    for line in input_data:
        tokens = line.split()
        _process_tokens(tokens, stack, definitions)

    return stack


def _process_tokens(tokens, stack, definitions):
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == ":":
            end = tokens.index(";", i)
            name = tokens[i + 1].lower()
            if _is_number(name):
                raise ValueError("illegal operation")
            body = tokens[i + 2:end]
            expanded = []
            for word in body:
                lower = word.lower()
                if lower in definitions:
                    expanded.extend(definitions[lower])
                else:
                    expanded.append(word)
            definitions[name] = expanded
            i = end + 1
            continue
        else:
            _execute(token, stack, definitions)
            i += 1


def _execute(token, stack, definitions):
    lower = token.lower()

    if _is_number(token):
        stack.append(int(token))
        return

    if lower in definitions:
        for word in definitions[lower]:
            _execute(word, stack, definitions)
        return

    if lower == "+":
        _require(stack, 2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a + b)
    elif lower == "-":
        _require(stack, 2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a - b)
    elif lower == "*":
        _require(stack, 2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a * b)
    elif lower == "/":
        _require(stack, 2)
        b = stack.pop()
        a = stack.pop()
        if b == 0:
            raise ZeroDivisionError("divide by zero")
        stack.append(a // b if (a < 0) == (b < 0) or a % b == 0 else -(-a // b) if a < 0 else -(a // -b))
    elif lower == "dup":
        _require(stack, 1)
        stack.append(stack[-1])
    elif lower == "drop":
        _require(stack, 1)
        stack.pop()
    elif lower == "swap":
        _require(stack, 2)
        stack[-1], stack[-2] = stack[-2], stack[-1]
    elif lower == "over":
        _require(stack, 2)
        stack.append(stack[-2])
    else:
        raise ValueError("undefined operation")


def _require(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")
