def _right_of(a, b):
    """House a is immediately to the right of house b."""
    return a - b == 1


def _next_to(a, b):
    return abs(a - b) == 1


def _solve():
    houses = (1, 2, 3, 4, 5)

    for red, green, ivory, yellow, blue in permutations(houses):
        if not _right_of(green, ivory):
            continue

        for englishman, spaniard, ukrainian, norwegian, japanese in permutations(houses):
            if englishman != red:
                continue
            if norwegian != 1:
                continue
            if not _next_to(norwegian, blue):
                continue

            for coffee, tea, milk, oj, water in permutations(houses):
                if coffee != green:
                    continue
                if ukrainian != tea:
                    continue
                if milk != 3:
                    continue

                for dog, snail, fox, horse, zebra in permutations(houses):
                    if spaniard != dog:
                        continue

                    for dancing, painter, reading, football, chess in permutations(houses):
                        if snail != dancing:
                            continue
                        if yellow != painter:
                            continue
                        if not _next_to(reading, fox):
                            continue
                        if not _next_to(painter, horse):
                            continue
                        if oj != football:
                            continue
                        if japanese != chess:
                            continue

                        nationalities = {
                            englishman: "Englishman",
                            spaniard: "Spaniard",
                            ukrainian: "Ukrainian",
                            norwegian: "Norwegian",
                            japanese: "Japanese",
                        }

                        water_drinker = nationalities[water]
                        zebra_owner = nationalities[zebra]
                        return water_drinker, zebra_owner


_WATER_DRINKER, _ZEBRA_OWNER = _solve()


def drinks_water():
    return _WATER_DRINKER


def owns_zebra():
    return _ZEBRA_OWNER
