pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    rolls: Vec<u16>,
    frame: u8,
    frame_rolls: Vec<u16>,
    game_over: bool,
}

impl BowlingGame {
    pub fn new() -> Self {
        BowlingGame {
            rolls: Vec::new(),
            frame: 1,
            frame_rolls: Vec::new(),
            game_over: false,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.game_over {
            return Err(Error::GameComplete);
        }
        if pins > 10 {
            return Err(Error::NotEnoughPinsLeft);
        }

        if self.frame < 10 {
            if self.frame_rolls.is_empty() {
                self.frame_rolls.push(pins);
                self.rolls.push(pins);
                if pins == 10 {
                    self.frame += 1;
                    self.frame_rolls.clear();
                }
            } else {
                let first = self.frame_rolls[0];
                if first + pins > 10 {
                    return Err(Error::NotEnoughPinsLeft);
                }
                self.frame_rolls.push(pins);
                self.rolls.push(pins);
                self.frame += 1;
                self.frame_rolls.clear();
            }
        } else {
            match self.frame_rolls.len() {
                0 => {
                    self.frame_rolls.push(pins);
                    self.rolls.push(pins);
                }
                1 => {
                    let first = self.frame_rolls[0];
                    if first != 10 && first + pins > 10 {
                        return Err(Error::NotEnoughPinsLeft);
                    }
                    self.frame_rolls.push(pins);
                    self.rolls.push(pins);
                    if first != 10 && first + pins < 10 {
                        self.game_over = true;
                    }
                }
                _ => {
                    let first = self.frame_rolls[0];
                    let second = self.frame_rolls[1];
                    if first == 10 && second != 10 && second + pins > 10 {
                        return Err(Error::NotEnoughPinsLeft);
                    }
                    self.frame_rolls.push(pins);
                    self.rolls.push(pins);
                    self.game_over = true;
                }
            }
        }

        Ok(())
    }

    pub fn score(&self) -> Option<u16> {
        if !self.game_over {
            return None;
        }

        let mut score: u16 = 0;
        let mut i = 0;
        for _ in 0..9 {
            if self.rolls[i] == 10 {
                score += 10 + self.rolls[i + 1] + self.rolls[i + 2];
                i += 1;
            } else if self.rolls[i] + self.rolls[i + 1] == 10 {
                score += 10 + self.rolls[i + 2];
                i += 2;
            } else {
                score += self.rolls[i] + self.rolls[i + 1];
                i += 2;
            }
        }
        score += self.rolls[i..].iter().sum::<u16>();

        Some(score)
    }
}
"}

